    [@odata.etag]      TEXT NULL,
    ownerid            TEXT NULL,
    systemuserid       TEXT NULL,
    [@odata.etag_json] TEXT NULL,
    ownerid_json       TEXT NULL,
    systemuserid_json  TEXT NULL
